                {'text': "Drones attacked Yandex's data center again in Vladimir, Russia", 'url': 'https://ua.news/en/war-vs-rf/video-u-rosiiskomu-volodimiri-droni-povtorno-atakuvali-data-tsentr-iandeksa', 'external': True, 'note': 'UA.News, Oct. 16'},
