                {'text': "Ukraine Hits Russia's $1 Billion Sberbank Mega Data Center in New Drone Strike", 'url': 'https://united24media.com/war-in-ukraine/ukraine-hits-russias-1-billion-sberbank-mega-data-center-in-new-drone-strike-23416', 'external': True, 'note': 'United24 Media'},
                {'text': 'Ukrainian drones hit Yandex data centers, sparking claims that Russian troll farms went quiet', 'url': 'https://www.helpnetsecurity.com/2026/10/13/ukraine-drone-strikes-yandex-data-centers/', 'external': True, 'note': 'Help Net Security, Oct. 13'},
